from e2e_common import *
with sync_playwright() as p:
    b=p.chromium.launch()
    pg=page(b,viewport={"width":1440,"height":900}); pg.goto(B+"/index.html")
    for key,label in (("services","Services"),("branches","Our Branches"),("library","Health Library")):
        pg.hover(f".nav__row:has(button[aria-controls=sub-{key}])"); ok(f"hover opens {label} dropdown",pg.is_visible(f"#sub-{key}"))
    pg.mouse.move(700,500); pg.wait_for_timeout(200)
    pg.focus("button[aria-controls=sub-branches]"); pg.keyboard.press("Enter"); ok("Enter opens branches dropdown",pg.get_attribute("button[aria-controls=sub-branches]","aria-expanded")=="true")
    ok("branches dropdown: 6 branches + main centre + all",pg.locator("#sub-branches li").count()==8)
    pg.keyboard.press("Escape"); ok("Escape closes dropdown",pg.get_attribute("button[aria-controls=sub-branches]","aria-expanded")=="false")
    pg.goto(B+"/index.html"); pg.keyboard.press("Tab"); ok("first Tab focuses skip link",pg.evaluate("document.activeElement.className")=="skip-link")
    ok("nav has all 9 required items",all(t in pg.inner_text("header") for t in ("Home","About Us","Services","Our Branches","Homecare","Health Library","FAQs","Contact Us","Request Appointment")))
    m=page(b,viewport={"width":390,"height":844}); m.goto(B+"/index.html")
    ok("mobile menu hidden initially",not m.is_visible("#site-nav")); m.click(".nav-toggle"); ok("mobile menu opens",m.is_visible("#site-nav"))
    m.click("button[aria-controls=sub-branches]"); ok("mobile branches submenu opens",m.is_visible("#sub-branches a[href$='eldoret.html']"))
    m.keyboard.press("Escape"); ok("Escape closes mobile menu",not m.is_visible("#site-nav")); ok("mobile action bar visible",m.is_visible(".mobile-bar"))
    t=page(b,viewport={"width":820,"height":1100}); t.goto(B+"/index.html"); t.click(".nav-toggle"); ok("tablet menu works",t.is_visible("#site-nav a[href$='branches/index.html']"))
    pg.goto(B+"/index.html"); pg.select_option("#find-branch","branches/nairobi.html"); pg.click(".findbar__form button"); pg.wait_for_url("**/branches/nairobi.html"); ok("home picker opens branch page",True)
    pg.goto(B+"/branches/index.html"); pg.fill("#branch-search","eld"); v=pg.locator("[data-branch]:visible").count(); ok("search 'eld' -> only Eldoret",v==1 and pg.is_visible("#eldoret"),v)
    pg.fill("#branch-search","zzz"); ok("no-match shows central line",pg.is_visible("[data-empty]") and "+254 726 094 695" in pg.inner_text("[data-empty]"))
    pg.click(".finder__clear"); ok("clear restores all 7",pg.locator("[data-branch]:visible").count()==7)
    pg.goto(B+"/appointments.html?branch=meru-farm"); ok("?branch= preselects",pg.input_value("#ap-branch")=="meru-farm"); ok("chip synced",pg.get_attribute("[data-pick-branch=meru-farm]","aria-pressed")=="true")
    pg.click("[data-pick-branch=tiwani]"); ok("chip changes select",pg.input_value("#ap-branch")=="tiwani")
    pg.select_option("#ap-branch",""); pg.click("#appointment-form button[type=submit]")
    ok("empty submit: summary + field errors",pg.is_visible("#appointment-form .form-status.is-error") and pg.locator("#appointment-form .field-error").count()>=4); ok("branch error is clear","branch" in pg.inner_text("#ap-branch-err").lower())
    pg.fill("#ap-name","E2E Patient"); pg.fill("#ap-phone","0712345678"); pg.select_option("#ap-branch","eldoret"); pg.select_option("#ap-service","laboratory"); pg.check("#ap-consent"); pg.click("#appointment-form button[type=submit]")
    pg.wait_for_selector("#appointment-form .is-success"); t_=pg.inner_text("#appointment-form .is-success"); ok("success shows reference and branch","NC-" in t_ and "Eldoret" in t_,t_[:80])
    pg.goto(B+"/branches/nairobi.html"); ok("branch page form preselects its branch",pg.input_value("#bp-branch")=="nairobi")
    pg.fill("#bp-name","Branch Page Person"); pg.fill("#bp-phone","0722000111"); pg.select_option("#bp-service","pharmacy"); pg.check("#bp-consent"); pg.click("#book button[type=submit]"); pg.wait_for_selector("#book .is-success")
    pg.goto(B+"/contact.html?branch=manor-house"); ok("contact preselect",pg.input_value("#ct-branch")=="manor-house")
    pg.fill("#ct-name","Contact Person"); pg.fill("#ct-email","c@example.com"); pg.fill("#ct-message","Hello"); pg.check("#ct-consent"); pg.click("#message button[type=submit]"); pg.wait_for_selector("#message .is-success")
    pg.goto(B+"/homecare.html"); pg.fill("#hc-requester_name","Family Member"); pg.fill("#hc-phone","0733000222"); pg.select_option("#hc-care_type","Nursing visit"); pg.select_option("#hc-branch","tiwani"); pg.fill("#hc-area","Some Estate"); pg.check("#hc-consent"); pg.click("#request button[type=submit]"); pg.wait_for_selector("#request .is-success")
    pg.route("**/api/enquiry",lambda r:r.abort()); pg.goto(B+"/contact.html"); pg.fill("#ct-name","X"); pg.fill("#ct-email","c@example.com"); pg.fill("#ct-message","Hi"); pg.check("#ct-consent"); pg.click("#message button[type=submit]")
    pg.wait_for_selector("#message .is-error"); e=pg.inner_text("#message .is-error"); ok("network failure shows phone fallback","+254 726 094 695" in e and "Nothing has been saved" in e)
    b.close()
c=sqlite3.connect("/tmp/e2e.db"); rows=c.execute("SELECT kind,name,branch,json_extract(payload,'$.branch') FROM enquiries ORDER BY id").fetchall(); print(rows)
exp=[("appointment","E2E Patient","eldoret","eldoret"),("appointment","Branch Page Person","nairobi","nairobi"),("contact","Contact Person","manor-house","manor-house"),("homecare","Family Member","tiwani","tiwani")]
ok("branch persisted (column + payload) for all 4 form kinds",rows==exp)
print("SUMMARY B",sum(v for _,v in res),"/",len(res))
